<?php require '_layout.php';$pdo=db();$items=[];if($pdo)try{$items=$pdo->query('SELECT m.*,COUNT(c.id) color_count FROM materials m LEFT JOIN material_colors c ON c.material_id=m.id GROUP BY m.id ORDER BY m.id DESC')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){}admin_header('Quản lý chất liệu','materials');admin_flash();?><section class="products-admin"><div class="dashboard-actions"><div><div class="kicker">Thư viện vật liệu</div><h2>Quản lý chất liệu</h2><p>Thiết lập hệ số, ảnh mẫu và bảng màu cho từng chất liệu.</p></div><a class="admin-button" href="material-form.php"><i class="bi bi-plus-lg"></i> Thêm chất liệu</a></div><div class="toolbar"><label class="search"><i class="bi bi-search"></i><input type="search" placeholder="Tìm tên hoặc mã..." data-material-search></label></div><?php if(!$pdo):?><div class="notice error">MySQL chưa kết nối.</div><?php elseif(!$items):?><div class="empty"><i class="bi bi-layers"></i><h3>Chưa có chất liệu</h3><a class="admin-button" href="material-form.php">+ Thêm chất liệu</a></div><?php else:?><div class="product-table material-table"><div class="table-row table-head"><span>Chất liệu</span><span>Mã</span><span>Hệ số</span><span>Màu</span><span></span></div><?php foreach($items as $item):?><article class="table-row" data-material-row data-search="<?=htmlspecialchars(mb_strtolower($item['name'].' '.$item['code']))?>"><div class="admin-product"><?php if($item['image']):?><img src="<?=htmlspecialchars($item['image'])?>" alt=""><?php else:?><span class="image-empty"><i class="bi bi-image"></i></span><?php endif?><div><b><?=htmlspecialchars($item['name'])?></b><small><?=htmlspecialchars($item['notes']?:'Chưa có ghi chú')?></small></div></div><code><?=htmlspecialchars($item['code'])?></code><strong>× <?=number_format($item['coefficient'],2,',','.')?></strong><span><i class="bi bi-palette"></i> <?=$item['color_count']?> màu</span><div class="table-actions"><a href="material-form.php?id=<?=$item['id']?>">Sửa</a><form method="post" action="material-delete.php" onsubmit="return confirm('Xoá chất liệu và toàn bộ màu?')"><input type="hidden" name="id" value="<?=$item['id']?>"><button>Xoá</button></form></div></article><?php endforeach?></div><?php endif?></section><?php admin_footer(); ?>
